const row = $input.first().json;
const hasDraft = !!(row.ai_TechnicalDraft && row.ai_TechnicalDraft.trim());

// Тот же предохранитель, что на обычном пути одобрения: черновик — это ещё
// не гарантия, что отдельные поля (оверлей, заголовок, хэштеги, теги) реально
// заполнены save_technical_draft-ом хотя бы раз.
// Список обязательных полей читается из таблицы (Templates →
// tmpl_RequiredTechFields) — см. пояснение в "Проверка полноты пакета"
// (обычный путь). Если колонки нет — используется прежний захардкоженный
// список (description сюда сознательно не входил и здесь тоже не входит).
function getRequiredKeys() {
  const defaults = ['overlayPosition', 'title', 'hashtags', 'tags'];
  try {
    const tmpl = $('Читаем шаблоны канала').first().json;
    const key = Object.keys(tmpl).find(k => k.replace(/^[^a-zA-Z]+/, '') === 'tmpl_RequiredTechFields');
    const raw = key && tmpl[key];
    if (!raw || !String(raw).trim()) return defaults;
    return String(raw).split(',').map(s => s.trim()).filter(Boolean);
  } catch (e) {
    return defaults;
  }
}

const fieldMap = {
  overlayPosition: row.ai_OverlayPosition,
  title: row.ai_Title,
  hashtags: row.ai_Hashtags,
  tags: row.ai_Tags,
  description: row.ai_Description,
};
const missingFields = getRequiredKeys().filter(key => !fieldMap[key] || !String(fieldMap[key]).trim());

// Та же проверка метки [Timecodes], что и на обычном пути одобрения —
// без неё 04_Video не сможет вписать тайм-коды в готовое видео. Это
// техническая необходимость, не настраивается из таблицы. Ищем гибко —
// со скобками или без, любым регистром — раз модель не всегда пишет
// их точь-в-точь, а 04_Video теперь тоже ищет её гибко.
if (row.ai_Description && !/\[?Timecodes\]?/i.test(row.ai_Description)) {
  missingFields.push('[Timecodes] (метка отсутствует в тексте описания)');
}

return [{
  json: {
    sys_ProjectID: row.sys_ProjectID,
    hasDraft,
    technicalDraft: row.ai_TechnicalDraft || '',
    missingFields,
  }
}];

function stripLabel(key) {
  return key.replace(/^[^a-zA-Z]+/, '');
}

function extractSection(text, tag) {
  if (!text) return '';
  const re = new RegExp('###' + tag + '###([\\s\\S]*?)###/' + tag + '###');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

function collectByIcon(tmpl, icon) {
  const parts = [];
  for (const key of Object.keys(tmpl)) {
    if (key.includes('tmpl_SystemPrompt')) continue;
    if (key.includes(icon)) {
      const value = tmpl[key];
      if (value) parts.push(stripLabel(key) + ':\n' + value);
    }
  }
  return parts.join('\n\n');
}

const tmpl = $input.first().json;

const systemPromptKey = Object.keys(tmpl).find(k => k.includes('tmpl_SystemPrompt'));
const roleNotes = extractSection(tmpl[systemPromptKey], 'ТЕХНИЧЕСКОЕ');
const sharedKnowledgeText = collectByIcon(tmpl, '🖋');
const knowledgeText = (roleNotes ? 'SystemPrompt (техническая часть):\n' + roleNotes + '\n\n' : '') + sharedKnowledgeText;

return [{ json: { knowledgeText } }];

const trigger = $('Вход от диспетчера').first().json;
const project = $('Читаем строку проекта').first().json;
const context = $('Находим шаблон канала').first().json;

const role = `Ты — редактор канала "${trigger.sheetName}", соавтор и собеседник автора канала. Сейчас идёт этап ТЕХНИЧЕСКОЙ ЧАСТИ: картинка и описание уже согласованы (картинка приложена к этому сообщению — посмотри на неё, она нужна тебе для решения про оверлей), и вместе с автором вы собираете последний пакет перед сборкой видео: текст оверлея на экране, заголовок, хэштеги/теги и технический подвал с указанием музыки. Говори свободно и живо, как обычный человек в разговоре — это не анкета и не чек-лист.\n\nПо структуре пакета ориентируйся на правила ниже (OVERLAY TEXT, TITLE, TECHNICAL FOOTER, SUBSCRIBE INVITATION, HASHTAGS & TAGS) — они лежат в базе канала. Для позиции оверлея на экране — посмотри на картинку: если главный объект сцены расположен ближе к одному краю, текст лучше разместить с другой стороны, чтобы его не перекрывать.\n\nФинальное английское описание для YouTube собирается из уже одобренного текста автора (он у тебя есть ниже, среди данных проекта) плюс технического подвала, приглашения подписаться и метки [Timecodes] на своём месте — просто соедини их в одно целое, не переписывая сам текст истории.\n\nУ тебя есть три инструмента (function tools):\n- save_technical_draft — вызывай каждый раз, когда предлагаешь автору конкретный, готовый к прочтению вариант всего пакета — передавай его одним читаемым текстом целиком (не разбивай на отдельные поля для показа), даже если это ещё черновик.\n- approve_technical — вызывай вместе с теми же словами, которыми сообщаешь автору, что весь пакет согласован и финален. Если ты произносишь эти слова, но не вызываешь инструмент в тот же момент, получается недоразумение: по твоим словам всё готово, а по факту в таблице ничего не изменилось. Дело не в том, чтобы меньше говорить или спешить — оставайся живой и свободной в разговоре, просто пусть финальное решение долетит и до таблицы, не только до собеседника.\n- update_communication_notes — как и на прошлых этапах: короткие, редкие заметки про стиль общения или неоднозначности в правилах, если правда есть чему научиться.\n\nБаза канала (правила упаковки, паспорт персонажа, локации, заметки — используй по смыслу подписи каждого блока):\n${context.knowledgeText}`;

return [{
  json: {
    conversationId: project.sys_ConversationId,
    systemPrompt: role,
    userMessage: trigger.messageText,
    approvedImageUrl: project.ai_ApprovedImageUrl,
    approvedDescriptionEN: project.ai_DescriptionEN,
    projectId: trigger.projectId,
    chatId: trigger.chatId,
    sheetName: trigger.sheetName,
    channelKey: trigger.channelKey,
  }
}];

const prep = $('Готовим запрос техчасти').first().json;
let conversationId = prep.conversationId;
if (!conversationId) {
  try { conversationId = $('Сохраняем ID разговора (техчасть)').first().json.conversationId; } catch (e) {}
}
const project = $('Читаем строку проекта').first().json;
return [{
  json: {
    ...prep,
    conversationId,
    pendingCallId: project.sys_ConversationId ? (project.sys_PendingToolCallId || '') : '',
  }
}];

const response = $input.first().json;
const output = response.output || [];

const messageItem = output.find(item => item.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const plainText = textPart ? textPart.text : '';

const callItem = output.find(item => item.type === 'function_call');

let action = 'chat';
let messageToUser = plainText;
let overlayText = '', overlayPosition = '', title = '', hashtags = '', tags = '', finalDescriptionEN = '', pinnedComment = '', readableDraft = '';
let communicationNotes = '';
let callId = null;
let functionName = null;

if (callItem) {
  callId = callItem.call_id;
  functionName = callItem.name;
  let args = {};
  try { args = JSON.parse(callItem.arguments || '{}'); } catch (e) {}
  messageToUser = args.messageToUser || plainText || '';

  if (functionName === 'save_technical_draft' || functionName === 'approve_technical') {
    action = functionName === 'approve_technical' ? 'approved' : 'draft';
    overlayText = args.overlayText || '';
    overlayPosition = args.overlayPosition || 'center';
    title = args.title || '';
    hashtags = args.hashtags || '';
    tags = args.tags || '';
    finalDescriptionEN = args.finalDescriptionEN || '';
    pinnedComment = args.pinnedComment || '';
    readableDraft = args.readableDraft || '';
  } else if (functionName === 'update_communication_notes') {
    communicationNotes = args.notes || '';
  }
}

const prep = $('Собираем финальный запрос').first().json;

return [{
  json: {
    action,
    messageToUser,
    overlayText,
    overlayPosition,
    title,
    hashtags,
    tags,
    finalDescriptionEN,
    pinnedComment,
    readableDraft,
    communicationNotes,
    callId,
    functionName,
    conversationId: prep.conversationId,
    projectId: prep.projectId,
    chatId: prep.chatId,
    sheetName: prep.sheetName,
    channelKey: prep.channelKey,
  }
}];

