const req = $('Готовим запрос техчасти').first().json;
const parsed = $('Парсим ответ техчасти').first().json;

return [{
  json: {
    classifierInput: `Автор написал: "${req.userMessage}"\n\nРедактор ответил: "${parsed.messageToUser}"`,
  }
}];

const response = $input.first().json;
const output = response.output || [];
const messageItem = output.find(i => i.type === 'message');
const textPart = messageItem && (messageItem.content || []).find(c => c.type === 'output_text');
const raw = (textPart ? textPart.text : '').trim().toLowerCase();

// Раньше любой нестандартный ответ классификатора (сбой запроса, обрезанный
// или неожиданный текст — что угодно, кроме чистого 'true') тихо считался
// тем же самым, что 'false' — то есть настоящий сбой проверки был неотличим
// от честного "автор не согласовывал", и терялся без единого следа.
// Различаем явно: 'approved' / 'not_approved' / 'uncertain'.
let classifierResult;
if (raw.startsWith('true')) {
  classifierResult = 'approved';
} else if (raw.startsWith('false')) {
  classifierResult = 'not_approved';
} else {
  classifierResult = 'uncertain';
}
const isApproved = classifierResult === 'approved';

const parsed = $('Парсим ответ техчасти').first().json;
return [{ json: { ...parsed, isApproved, classifierResult, classifierRaw: raw } }];

