// Технический предохранитель: не полагаемся только на словесную просьбу
// к модели 'сама проверь перед Утверждено' — здесь это проверяется программно,
// прежде чем статус вообще может смениться на 'Утверждено'.
const j = $input.first().json;

// Список обязательных полей теперь читается из таблицы (Templates →
// tmpl_RequiredTechFields, через запятую, например "overlayPosition,title") —
// чтобы не перешивать код каждый раз, когда меняется, что считать
// обязательным для конкретного канала. Если колонки нет или она пустая —
// используется тот же список, что был здесь захардкожен раньше.
// overlayPosition/title/hashtags/tags/description сознательно не включают
// overlayText — для некоторых выпусков (например, насыщенных текстом
// инфографик-гайдов) оверлей теперь осознанно оставляют пустым, это не
// пропуск, а решение.
function getRequiredKeys() {
  const defaults = ['overlayPosition', 'title', 'hashtags', 'tags', 'description'];
  try {
    const tmpl = $('Читаем шаблоны канала').first().json;
    const key = Object.keys(tmpl).find(k => k.replace(/^[^a-zA-Z]+/, '') === 'tmpl_RequiredTechFields');
    const raw = key && tmpl[key];
    if (!raw || !String(raw).trim()) return defaults;
    return String(raw).split(',').map(s => s.trim()).filter(Boolean);
  } catch (e) {
    return defaults;
  }
}

const fieldMap = {
  overlayPosition: j.overlayPosition,
  title: j.title,
  hashtags: j.hashtags,
  tags: j.tags,
  description: j.finalDescriptionEN,
};
const missingFields = getRequiredKeys().filter(key => !fieldMap[key] || !String(fieldMap[key]).trim());

// [Timecodes] — не просто ещё одно поле из таблицы, а буквальная строка,
// которую 04_Video ищет и заменяет на реальные тайм-коды. Это техническая
// необходимость самого пайплайна, а не творческий выбор — поэтому она не
// настраивается из таблицы и проверяется отдельно всегда. Ищем гибко — со
// скобками или без, любым регистром — раз модель не всегда пишет их
// точь-в-точь, а 04_Video теперь тоже ищет её гибко.
if (j.finalDescriptionEN && !/\[?Timecodes\]?/i.test(j.finalDescriptionEN)) {
  missingFields.push('[Timecodes] (метка отсутствует в тексте описания)');
}

return [{ json: { ...j, missingFields } }];

// Тот же предохранитель, что и на основном пути 'Ставим статус Утверждено',
// но здесь данные берём не из ответа модели, а прямо из таблицы —
// этот путь срабатывает, когда пользователь просто согласился словами
// в чате, а не через явный вызов инструмента с новыми данными.
const j = $input.first().json;

// Список обязательных полей читается из таблицы (Templates →
// tmpl_RequiredTechFields) — см. пояснение в "Проверка полноты пакета"
// (обычный путь). Если колонки нет — используется прежний захардкоженный
// список.
function getRequiredKeys() {
  const defaults = ['overlayPosition', 'title', 'hashtags', 'tags', 'description'];
  try {
    const tmpl = $('Читаем шаблоны канала').first().json;
    const key = Object.keys(tmpl).find(k => k.replace(/^[^a-zA-Z]+/, '') === 'tmpl_RequiredTechFields');
    const raw = key && tmpl[key];
    if (!raw || !String(raw).trim()) return defaults;
    return String(raw).split(',').map(s => s.trim()).filter(Boolean);
  } catch (e) {
    return defaults;
  }
}

const fieldMap = {
  overlayPosition: j.ai_OverlayPosition,
  title: j.ai_Title,
  hashtags: j.ai_Hashtags,
  tags: j.ai_Tags,
  description: j.ai_Description,
};
const missingFields = getRequiredKeys().filter(key => !fieldMap[key] || !String(fieldMap[key]).trim());
return [{ json: { ...j, missingFields } }];
